set -euo pipefail; SDK="${ANDROID_SDK_ROOT:-${ANDROID_HOME:-$HOME/Library/Android/sdk}}"; ADB="$SDK/platform-tools/adb"; SERIAL=$("$ADB" devices | awk 'NR>1 && $2=="device" {print $1; exit}'); test -n "$SERIAL"; SOCKET=$("$ADB" -s "$SERIAL" shell cat /proc/net/unix | sed -n 's/.*@\(webview_devtools_remote_[0-9]*\)$/\1/p' | tail -1 | tr -d '\r'); test -n "$SOCKET"; "$ADB" -s "$SERIAL" forward --remove tcp:9222 >/dev/null 2>&1 || true; "$ADB" -s "$SERIAL" forward tcp:9222 localabstract:"$SOCKET" >/dev/null; node --input-type=module - <<'NODE'
const TARGET='shellyplugsg3-e4b063e3e298';
const EXPECTED='E4:B0:63:E3:E2:9A';
const STALE='02:00:00:00:00:01';
const KEY='lcl.savedBlePlugs.v1';
const targets=await fetch('http://127.0.0.1:9222/json/list').then(r=>r.json());
const target=targets.find(t=>t.type==='page')??targets[0];
if(!target?.webSocketDebuggerUrl) throw new Error('No debuggable WebView target');
const ws=new WebSocket(target.webSocketDebuggerUrl); let nextId=1; const pending=new Map();
ws.onmessage=e=>{const m=JSON.parse(e.data); if(m.id&&pending.has(m.id)){pending.get(m.id)(m);pending.delete(m.id)}};
await new Promise((r,j)=>{ws.onopen=r;ws.onerror=j});
const call=(method,params={})=>new Promise((resolve,reject)=>{const id=nextId++; const timer=setTimeout(()=>{pending.delete(id);reject(new Error('CDP timeout '+method));},15000); pending.set(id,(msg)=>{clearTimeout(timer);resolve(msg)}); ws.send(JSON.stringify({id,method,params}));});
const evalValue=async(expression)=>{const res=await call('Runtime.evaluate',{expression,returnByValue:true,awaitPromise:true}); if(res.result?.exceptionDetails) throw new Error('Runtime.evaluate exception: '+JSON.stringify(res.result.exceptionDetails)); return res.result?.result?.value;};
const snapshotExpr=`(()=>{const raw=localStorage.getItem(${JSON.stringify(KEY)}); const parsed=raw?JSON.parse(raw):null; const plug=parsed?.plugs?.find(p=>String(p.physicalId).trim().toLowerCase()===${JSON.stringify(TARGET)}); const cards=[...document.querySelectorAll('article.automation-card.plug-card--unconfigured')].map(card=>({text:card.innerText,buttons:[...card.querySelectorAll('button')].map(b=>({text:b.textContent?.trim(),pressed:b.getAttribute('aria-pressed'),disabled:b.disabled})),alerts:[...card.querySelectorAll('[role=alert]')].map(x=>x.textContent?.trim())})); return JSON.stringify({raw,plug,cards,body:document.body.innerText.slice(0,8000)});})()`;
const before=JSON.parse(await evalValue(snapshotExpr));
if(!before.plug) throw new Error('Target saved BLE Plug missing');
if(before.plug.bleDeviceId!==EXPECTED) throw new Error('Unexpected starting locator: '+before.plug.bleDeviceId);
const targetCard=before.cards.find(c=>c.text.includes(before.plug.name));
if(!targetCard) throw new Error('Target BLE-only dashboard card not found');
const offButton=targetCard.buttons.find(b=>b.text==='OFF');
if(!offButton||offButton.pressed!=='true') throw new Error('Target relay is not confirmed OFF before acceptance; refusing to continue');
console.log('BEFORE='+JSON.stringify({plug:before.plug,card:targetCard}));
const beforeMeta={...before.plug}; delete beforeMeta.bleDeviceId;
const staleResult=await evalValue(`(()=>{const raw=localStorage.getItem(${JSON.stringify(KEY)}); const parsed=JSON.parse(raw); const plug=parsed.plugs.find(p=>String(p.physicalId).trim().toLowerCase()===${JSON.stringify(TARGET)}); if(!plug) throw new Error('target missing'); if(plug.bleDeviceId!==${JSON.stringify(EXPECTED)}) throw new Error('locator changed before stale injection'); plug.bleDeviceId=${JSON.stringify(STALE)}; localStorage.setItem(${JSON.stringify(KEY)},JSON.stringify(parsed)); return JSON.stringify(plug);})()`);
console.log('STALE_INJECTED='+staleResult);
await evalValue('location.reload(); true');
await new Promise(r=>setTimeout(r,2500));
let recovered=null;
for(let i=0;i<55;i++){
  try{
    const snap=JSON.parse(await evalValue(snapshotExpr));
    if(snap.plug?.bleDeviceId===EXPECTED){ recovered=snap; break; }
    if(snap.plug?.bleDeviceId!==STALE) throw new Error('Unexpected locator during recovery: '+snap.plug?.bleDeviceId);
  }catch(e){ if(i===54) throw e; }
  await new Promise(r=>setTimeout(r,2000));
}
if(!recovered) throw new Error('Locator recovery did not complete within acceptance window');
if(String(recovered.plug.physicalId).trim().toLowerCase()!==TARGET) throw new Error('physicalId changed');
const finalMeta={...recovered.plug}; delete finalMeta.bleDeviceId;
if(JSON.stringify(finalMeta)!==JSON.stringify(beforeMeta)) throw new Error('Saved Plug metadata changed beyond locator');
const finalCard=recovered.cards.find(c=>c.text.includes(recovered.plug.name));
if(!finalCard) throw new Error('Recovered BLE-only dashboard card missing');
const finalOff=finalCard.buttons.find(b=>b.text==='OFF');
if(!finalOff||finalOff.pressed!=='true'||finalOff.disabled) throw new Error('Recovered runtime did not settle to enabled OFF state');
if(finalCard.alerts.length) throw new Error('Recovered card still exposes an error: '+JSON.stringify(finalCard.alerts));
console.log('AFTER='+JSON.stringify({plug:recovered.plug,card:finalCard}));
console.log('ACCEPTANCE='+JSON.stringify({physicalId:recovered.plug.physicalId,beforeLocator:EXPECTED,staleLocator:STALE,afterLocator:recovered.plug.bleDeviceId,relay:'OFF',metadataPreserved:true}));
ws.close();
NODE
